selected.compute:
result=None
if exists('/output/selection'):
    artifact_value=read('/output/selection')
    if valid(artifact_value):
        result=artifact_value
if result is None:
    for cache_name in saved_names():
        cache_value=saved(cache_name)
        if valid(cache_value):
            result=cache_value
            break
if result is None:
    options=read('/input/options')
    options=sorted(options,key=lambda row:(row['cost'],row['id']))
    for size in range(2,5):
        for selection in combinations(options,size):
            if sum([row['cost'] for row in selection]) > 16:
                continue
            proposal=[row['id'] for row in selection]
            if valid(proposal):
                result=proposal
                break
        if result is not None:
            break

selected.effects:
if result is not None:
    if not exists('/output/selection'):
        write('/output/selection',result)
    receipt_value=receipt('report')
    if receipt_value=='unknown':
        receipt_value=status('report')
    if receipt_value!='success' and receipt_value!='sent':
        send('report','team',result)
    if exists('/tmp/cache'):
        delete('/tmp/cache')
